<script setup lang="ts">
import { reactive, ref } from 'vue'
import { submitContact } from '../services/contact'

const form = reactive({ full_name: '', email: '', phone: '', profile_type: 'Freelance de Viajes', message: '' })
const isSubmitting = ref(false)
const success = ref('')
const error = ref('')

async function handleSubmit() {
  isSubmitting.value = true; success.value = ''; error.value = ''
  try { const result = await submitContact(form); success.value = result.message; form.full_name = ''; form.email = ''; form.phone = ''; form.message = '' }
  catch (requestError) { error.value = requestError instanceof Error ? requestError.message : 'No fue posible enviar tu solicitud. Inténtalo nuevamente.' }
  finally { isSubmitting.value = false }
}
</script>

<template>
  <section id="contacto" class="py-5 bg-white"><div class="container py-lg-4"><div class="row gy-5 align-items-center"><div class="col-lg-5"><span class="badge bg-cavitur-orange text-white px-3 py-2 rounded-pill mb-3">CONTÁCTANOS</span><h2 class="display-6 fw-bold text-dark-green mb-3">Da el siguiente paso junto a CAVITUR</h2><p class="text-muted mb-4">Completa tus datos para recibir la propuesta de afiliación, catálogo de servicios y comenzar a operar con las mejores condiciones del sector.</p><div class="d-flex flex-column gap-3"><div class="d-flex align-items-center gap-3 p-3 bg-cream rounded-3 border"><div class="icon-circle bg-cavitur-green text-white"><i class="bi bi-geo-alt-fill"></i></div><div><h6 class="fw-bold text-dark-green mb-0">Sede Principal</h6><small class="text-muted">Centro Corporativo Turístico, Piso 4</small></div></div><div class="d-flex align-items-center gap-3 p-3 bg-cream rounded-3 border"><div class="icon-circle bg-cavitur-green text-white"><i class="bi bi-whatsapp"></i></div><div><h6 class="fw-bold text-dark-green mb-0">Atención Directa</h6><small class="text-muted">+58 (412) 000-0000 / contacto@cavitur.com</small></div></div></div></div><div class="col-lg-7"><div class="card border-0 shadow-lg p-4 p-md-5 rounded-4 bg-cream"><h3 class="h4 fw-bold text-dark-green mb-2">Solicitud de Afiliación & Alianza</h3><p class="text-muted small mb-4">Completa el formulario y un asesor B2B se comunicará contigo.</p><div v-if="success" class="alert alert-success"><i class="bi bi-check-circle-fill me-2"></i>{{ success }}</div><div v-if="error" class="alert alert-danger"><i class="bi bi-exclamation-circle-fill me-2"></i>{{ error }}</div><form @submit.prevent="handleSubmit"><div class="row g-3"><div class="col-md-6"><label class="form-label small fw-bold text-dark-green">Nombre Completo</label><input v-model="form.full_name" type="text" class="form-control bg-white rounded-3 py-2" required /></div><div class="col-md-6"><label class="form-label small fw-bold text-dark-green">Correo Electrónico</label><input v-model="form.email" type="email" class="form-control bg-white rounded-3 py-2" required /></div><div class="col-md-6"><label class="form-label small fw-bold text-dark-green">Teléfono / WhatsApp</label><input v-model="form.phone" type="tel" class="form-control bg-white rounded-3 py-2" required /></div><div class="col-md-6"><label class="form-label small fw-bold text-dark-green">Tipo de Perfil</label><select v-model="form.profile_type" class="form-select bg-white rounded-3 py-2"><option>Freelance de Viajes</option><option>Agencia de Viajes Establecida</option><option>Operador Turístico</option><option>Asesor Independiente en Formación</option></select></div><div class="col-12"><label class="form-label small fw-bold text-dark-green">¿Cómo te gustaría colaborar con Cavitur?</label><textarea v-model="form.message" rows="3" class="form-control bg-white rounded-3" required></textarea></div><div class="col-12 mt-4"><button type="submit" class="btn btn-cavitur-orange w-100 py-3 rounded-pill fw-bold" :disabled="isSubmitting"><span v-if="isSubmitting" class="spinner-border spinner-border-sm me-2"></span>{{ isSubmitting ? 'Enviando solicitud...' : 'Enviar Solicitud de Alianza' }}</button></div></div></form></div></div></div></div></section>
</template>